}
.viz-tick {
  fill: var(--viz-muted);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.viz-end-label {
  fill: var(--g-color-text-secondary);
  font-size: 12px;
}
.viz-line__path {
  fill: none;
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.viz-dot {
  stroke: var(--viz-surface);
